            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_bar.Close

        all_symbols_present = all(
            symbol in data.Bars
            for symbol in [self.spy, self.aapl, self.ibm, self.bac, self.aig]
        )

        if not all_symbols_present:
            if spy_bar is not None and current_spy_sma is not None:
                self.previous_spy_close = spy_bar.Close
                self.previous_spy_sma = current_spy_sma
            return

        spy_crosses_below = (
            spy_bar is not None
            and current_spy_sma is not None
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and spy_bar.Close < current_spy_sma
        )

        spy_crosses_above = (
            spy_bar is not None
            and current_spy_sma is not None
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and spy_bar.Close > current_spy_sma
        )

        aapl_sell = (
            self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > 60
        )

        aapl_buy = self.aapl_red_streak >= 3

        if self.lots["A"] > 0 and spy_crosses_below:
            self.MarketOrder(
                self.spy,
                -self.lots["A"],
                tag="A_SELL"
            )

        if self.lots["B"] > 0 and aapl_sell:
            self.MarketOrder(
                self.aapl,
                -self.lots["B"],
                tag="B_SELL"
            )

        if self.lots["A"] == 0 and spy_crosses_above:
            shares = int(
                (0.40 * self.Portfolio.TotalPortfolioValue) / spy_bar.Close
            )
            if shares > 0:
                self.MarketOrder(
                    self.spy,
                    shares,
                    tag="A_BUY"
                )

        if self.lots["B"] == 0 and aapl_buy:
            if self.Portfolio.Cash >= 20000:
                shares = int(20000 / aapl_bar.Close)
                if shares > 0:
                    self.MarketOrder(
                        self.aapl,
                        shares,
                        tag="B_BUY"
                    )

        if spy_bar is not None and current_spy_sma is not None:
            self.previous_spy_close = spy_bar.Close
            self.previous_spy_sma = current_spy_sma

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        tag = order.Tag

        if tag == "A_BUY":
            self.lots["A"] += order_event.FillQuantity
        elif tag == "A_SELL":
            self.lots["A"] += order_event.FillQuantity
            self.lots["A"] = max(0, self.lots["A"])
        elif tag == "B_BUY":
            self.lots["B"] += order_event.FillQuantity
        elif tag == "B_SELL":
            self.lots["B"] += order_event.FillQuantity
            self.lots["B"] = max(0, self.lots["B"])
