            self.strategy_b_lot = max(0, self.strategy_b_lot + fill_quantity)

        if order_event.Status in [
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled
        ]:
            if order_event.Status != OrderStatus.PartiallyFilled:
                del self.pending_orders[order_id]

    def OnData(self, data: Slice):
        bars = {}

        for symbol in self.symbols:
            if symbol not in data.Bars:
                return
            bars[symbol] = data.Bars[symbol]

        spy_close = float(bars[self.spy].Close)
        aapl_close = float(bars[self.aapl].Close)

        spy_previous_sma = None
        if len(self.spy_closes) >= 100:
            spy_previous_sma = sum(list(self.spy_closes)[-100:]) / 100.0

        self.spy_closes.append(spy_close)

        spy_current_sma = None
        if len(self.spy_closes) >= 100:
            spy_current_sma = sum(list(self.spy_closes)[-100:]) / 100.0

        aapl_previous_close = None
        if len(self.aapl_closes) > 0:
            aapl_previous_close = self.aapl_closes[-1]

        if aapl_previous_close is not None:
            if aapl_close < aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.aapl_closes.append(aapl_close)
        self.aapl_rsi.Update(self.Time, aapl_close)

        if self.IsWarmingUp:
            return

        strategy_a_buy = (
            spy_previous_sma is not None
            and spy_current_sma is not None
            and spy_close > spy_current_sma
            and self.spy_closes[-2] <= spy_previous_sma
        )

        strategy_a_sell = (
            spy_previous_sma is not None
            and spy_current_sma is not None
            and spy_close < spy_current_sma
            and self.spy_closes[-2] >= spy_previous_sma
        )

        strategy_b_buy = self.aapl_red_streak >= 3
        strategy_b_sell = self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60

        if self.strategy_a_lot > 0 and strategy_a_sell:
            self._sell_strategy_a()

        if self.strategy_b_lot > 0 and strategy_b_sell:
            self._sell_strategy_b()

        if self.strategy_a_lot == 0 and strategy_a_buy:
            self._buy_strategy_a(spy_close)

        if self.strategy_b_lot == 0 and strategy_b_buy:
            self._buy_strategy_b(aapl_close)

    def _buy_strategy_a(self, close):
        shares = int((0.40 * self.Portfolio.TotalPortfolioValue) / close)

        if shares <= 0:
            return

        ticket = self.MarketOrder(self.spy, shares)

        if ticket is not None:
            self.pending_orders[ticket.OrderId] = "A"

    def _sell_strategy_a(self):
        if self.strategy_a_lot <= 0:
            return

        ticket = self.MarketOrder(self.spy, -self.strategy_a_lot)

        if ticket is not None:
            self.pending_orders[ticket.OrderId] = "A"

    def _buy_strategy_b(self, close):
        cost = 20000

        if self.Portfolio.Cash < cost:
            return

        shares = int(cost / close)

        if shares <= 0:
            return

        ticket = self.MarketOrder(self.aapl, shares)

        if ticket is not None:
            self.pending_orders[ticket.OrderId] = "B"

    def _sell_strategy_b(self):
        if self.strategy_b_lot <= 0:
            return

        ticket = self.MarketOrder(self.aapl, -self.strategy_b_lot)

        if ticket is not None:
            self.pending_orders[ticket.OrderId] = "B"
